-- Dados fiéis ao Excel do cliente. A password é definida com BCrypt no arranque (SeedPasswords.java).
-- Pode executar-se repetidamente: ON CONFLICT evita duplicações.
SELECT setval(pg_get_serial_sequence('volunteers','id'),(SELECT COALESCE(MAX(id),1) FROM volunteers),true);
SELECT setval(pg_get_serial_sequence('shifts','id'),(SELECT COALESCE(MAX(id),1) FROM shifts),true);
SELECT setval(pg_get_serial_sequence('historical_attendance','id'),(SELECT COALESCE(MAX(id),1) FROM historical_attendance),true);
